local L = LibStub("AceLocale-3.0"):NewLocale("NeatPlates", "deDE")
if not L then return end


L = L or {}
L["Nameplate stacking is now controlled in Blizzard's Nameplate settings. Blizzard changed this behavior with Phase 5, so NeatPlates follows the Blizzard setting."] = "Das Stapeln von Namensplaketten wird jetzt in den Blizzard-Einstellungen unter 'Namensplaketten' gesteuert. Blizzard hat dieses Verhalten mit Phase 5 geaendert; NeatPlates folgt dieser Einstellung."
L["Stacking Nameplates"] = "Stapelnde Namensplaketten"
L["Spacing Offset"] = "Abstand Offset"
L["Vertical Spacing"] = "Vertikaler Abstand"
L["Controls Blizzard's vertical nameplate stacking distance. Smaller values keep nameplates closer together; larger values add more space."] = "Steuert Blizzards vertikalen Abstand fuer stapelnde Namensplaketten. Kleinere Werte ruecken sie enger zusammen; groessere Werte schaffen mehr Abstand."
L["Display Offset X"] = "Anzeige Offset X"
L["Display Offset Y"] = "Anzeige Offset Y"
L["Moves the NeatPlates overlay horizontally relative to Blizzard's real nameplate anchor. This does not change Blizzard stacking."] = "Verschiebt das NeatPlates-Overlay horizontal relativ zum echten Blizzard-Namensplaketten-Anker. Das aendert nicht Blizzards Stapelverhalten."
L["Moves the NeatPlates overlay vertically relative to Blizzard's real nameplate anchor. This does not change Blizzard stacking."] = "Verschiebt das NeatPlates-Overlay vertikal relativ zum echten Blizzard-Namensplaketten-Anker. Das aendert nicht Blizzards Stapelverhalten."
L["Ignore Blizzard Alpha"] = "Blizzard-Alpha ignorieren"
L["Uses NeatPlates profile opacity directly instead of multiplying it with Blizzard's nameplate alpha."] = "Verwendet die NeatPlates-Profil-Deckkraft direkt, statt sie mit Blizzards Nameplate-Alpha zu multiplizieren."
L["Ignore Tanked-by-Tank Mobs"] = "Ignore Tanked-by-Tank Mobs"
L["When you are tanking, enemies already held by another tank, pet, or guardian will not be highlighted."] = "Wenn du tankst, werden Gegner, die bereits von einem anderen Tank, Pet oder Begleiter gehalten werden, nicht hervorgehoben."
